class Solution {
public:
    vector<int> getSneakyNumbers(vector<int>& nums) {
        int n = (int)nums.size() - 2;
        vector<int> result;
        for (int i = 0; i < (int)nums.size(); i++) {
            int x = nums[i] % n;
            if (nums[x] >= n) {
                result.push_back(x);
            } else {
                nums[x] += n;
            }
        }
        return result;
    }
};
